    for c in range(n):
        result[c] = grid[c][:]
    return result  # This is transpose

# For 9-filling with transpose symmetry
def transpose_palindrome(grid, n):
    result = [[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            mirror = (c, r)
            if grid[r][c] != 9:
                result[r][c] = grid[r][c]
            if grid[mirror[0]][mirror[1]] != 9 and grid[mirror[0]][mirror[1]] != result[r][c]:
                result[r][c] = max(result[r][c], grid[mirror[0]][mirror[1]])
    return result

