def expand_with_fill_mirrors(input_grid, n):
    result = [[0]*(2*n) for _ in range(2*n)]

    # Fill TL directly
    for r in range(n):
        for c in range(n):
            result[r][c] = input_grid[r][c]

    # Fill TR: mirror horizontally (use input[r][n-1-c])
    for r in range(n):
        for c in range(n):
            # output position (r, n+c)
            # Map to: input_grid[r][?] -- which column?
            # If mirroring: possibly input_grid[r][c] or input_grid[r][n-1-c]
            # Let's try input[r][c] for simplicity first
            if input_grid[r][c] != 9:
                result[r][n+c] = input_grid[r][c]

    # Fill BL: mirror vertically
    for r in range(n):
        for c in range(n):
            # output position (n+r, c)
            if input_grid[r][c] != 9:
                result[n+r][c] = input_grid[r][c]

    # Fill BR: both mirrors
    for r in range(n):
        for c in range(n):
            # output position (n+r, n+c)
            if input_grid[r][c] != 9:
                result[n+r][n+c] = input_grid[r][c]

    return result

